VARIANTS = [('A base', '    int retry = 4;\r\n    do {\r\n        if (_cd_event_init() == 1) {\r\n            CD_cbsync        = (int)_cd_event_sync;\r\n            CD_cbready       = (int)_cd_event_ready;\r\n            CD_cbread        = (int)_cd_event_read;\r\n            CD_read_dma_mode = 0;\r\n            return 1;\r\n        }\r\n        retry--;\r\n    } while (retry != -1);'), ('B while-top', '    int retry = 4;\r\n    while (retry != -1) {\r\n        if (_cd_event_init() == 1) {\r\n            CD_cbsync        = (int)_cd_event_sync;\r\n            CD_cbready       = (int)_cd_event_ready;\r\n            CD_cbread        = (int)_cd_event_read;\r\n            CD_read_dma_mode = 0;\r\n            return 1;\r\n        }\r\n        retry--;\r\n    }'), ('C for-loop', '    int retry;\r\n    for (retry = 4; retry != -1; retry--) {\r\n        if (_cd_event_init() == 1) {\r\n            CD_cbsync        = (int)_cd_event_sync;\r\n            CD_cbready       = (int)_cd_event_ready;\r\n            CD_cbread        = (int)_cd_event_read;\r\n            CD_read_dma_mode = 0;\r\n            return 1;\r\n        }\r\n    }'), ('D continue-arm', '    int retry = 4;\r\n    do {\r\n        if (_cd_event_init() != 1) {\r\n            retry--;\r\n            continue;\r\n        }\r\n        CD_cbsync        = (int)_cd_event_sync;\r\n        CD_cbready       = (int)_cd_event_ready;\r\n        CD_cbread        = (int)_cd_event_read;\r\n        CD_read_dma_mode = 0;\r\n        return 1;\r\n    } while (retry != -1);'), ('E goto-loop', '    int retry = 4;\r\nloop:\r\n    if (_cd_event_init() == 1) {\r\n            CD_cbsync        = (int)_cd_event_sync;\r\n            CD_cbready       = (int)_cd_event_ready;\r\n            CD_cbread        = (int)_cd_event_read;\r\n            CD_read_dma_mode = 0;\r\n            return 1;\r\n    }\r\n    retry--;\r\n    if (retry != -1) goto loop;')]
